{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In rhesus monkeys, the polar glucuronide GAZT had a mean CSF/plasma ratio of only 0.04 at 1 h, directly demonstrating negligible BBB permeability for a glycosylated, polar molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In humans, 68Ga-PSMA-11 (947 Da) showed no brain uptake, attributed to molar mass above the BBB limit; the query is nearly twice as large, supporting inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A sulfonated adenosine derivative was undetectable in mouse brain (<0.1% of plasma) despite measurable plasma levels, showing that highly polar/ionized molecules fail to achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In rats, the multi-glycosylated polyphenol epimedin B was the least concentrated in brain among tissues, indicating that heavily glycosylated polyphenolic structures like the query do not cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In situ brain perfusion in rats gave a very low brain distribution clearance (4.5 µL/g/min) for a polar nucleoside analogue, supporting poor CNS access for similarly polar large molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Fail. The query is a very large, highly polar, fully ionized glycopeptide-like molecule. Multiple transferable in vivo measurements in monkeys, humans, rats, and mice show negligible brain uptake for similarly sized/polar glycosylated and high-MW compounds, and no evidence supports active CNS uptake.",
  "evidence_gaps": [
    "No direct CSF/plasma or brain/plasma measurement for the exact query molecule.",
    "No data on possible receptor-mediated transcytosis or active uptake for this specific glycopeptide.",
    "Assay-transfer scores are moderate (~0.64-0.67), so quantitative extrapolation is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

